\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 Ilgen S. 170 \u183 \'b7 P. Clemen, Die Kunstdenkm\u228 \'e4ler der Stadt und des Kreises D\u252 \'fcsseldorf, D\u252 \'fcsseldorf 1894 (Die Kunstdenkm\u228 \'e4ler der Rheinprovinz; 3,1), S. 55 (f\u228 \'e4lschlich als \u8222 \'84B. 106\ldblquote  genannt) \u183 \'b7 Landmann S. 51 f., 80, 83, 108, 169\endash 171, 181, 190\endash 192, 197 f., 233 \u183 \'b7 van de Pasch, Bibliotheca, S. 3, 39, 51 \u183 \'b7 J. B. Schneyer, Geschichte der katholischen Predigt, Freiburg 1969, S. 200 \u183 \'b7 Sottili Bd. 1, S. (67) \u183 \'b7 Kr\u228 \'e4mer S. 172 \u183 \'b7 Handschriftencensus Rheinland Nr. 562 \u183 \'b7 Finger, Bibliotheken, S. 226, Anm. 55 \u183 \'b7 Karpp-Jacottet, Marienfrede, S. 286.}

