\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 7\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \plain \f1\scaps\lang1033\fs26 Auctoritates patrum. \plain \f1\lang1033\fs26 Sammlung von Exzerpten und kurzen Notizen (darunter wenige dt. Interpretamente) zur Erg\u228 \'e4nzung der in der Hs. enthaltenen Predigten; genannte Autorit\u228 \'e4ten: {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Augustinus}}\plain \f1\lang1033\fs26 ,\plain \f1\i\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Crisostomus}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Hilarius}}\plain \f1\lang1033\fs26 . \endash  7\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  leer.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 8\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 451\plain \f1\super\lang1033\fs24 v\plain \f1\scaps\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Henricus Millingen}}\plain \f1\scaps\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Sermones de sanctis}}\plain \f1\scaps\lang1033\fs26 . \plain \f1\lang1033\fs26 >\plain \f1\i\lang1033\fs26 In festo sancti Andree apostoli. Sermo primus.\plain \f1\lang1033\fs26 < {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Magnificavit eum ... }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 [I Mcc 10,65]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 . Verba scribuntur 1 Machabeorum XI }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 [!] }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 capitulo, litteraliter de nobili principe Jonatha, transsumptive autem sumuntur pro exordio nostri presentis sermonis ad honorem sancti Andree apostoli}}\plain \f1\i\lang1033\fs26  ... {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Charissimi in Christo, verba ut supra et sic sonant: etc. }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 [offenbar zu erg\u228 \'e4nzen ist die dt. \u220 \'dcbersetzung des Themas] }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Que descripta sunt de nobili principe Jonatha}}\plain \f1\i\lang1033\fs26  ... \endash  ... \plain \f1\lang1033\fs26 [Sermo secundus de s. Katharina; Anfang fehlt, s.u.] \plain \f1\i\lang1033\fs26 Multo plura hic signa et miracula possent applicari sed quia tempus elapsum est ideo supersedeo. Honoremus et invocemus etc. \plain \f1\lang1033\fs26 >\plain \f1\i\lang1033\fs26 Expliciunt sermones de sanctis collecti per fratrem Henricum Millingen. Utentes eis orent pro eo.\plain \f1\lang1033\fs26 < Angeschlossen Exzerpt (9 Zeilen): {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Isidorus: Pavo cum pulchritudinem pennarum suarum cernit caudam erigit}}\plain \f1\i\lang1033\fs26  ... \plain \f1\lang1033\fs26 Bei Isidorus Hispalensis nicht nachweisbar. Bestand (Siglen nach Schneyer; Leg. = Legendentext anstelle Predigt): S1 (2x), Barbara (2x), S3 (2x), S 5 (3x), S7, S8 (2x), T6 (3x: \lquote In prima missa\rquote ; \lquote In aurora\rquote ; \lquote In summa missa\rquote ), S9 (4x), S10 (2x), S11 f., S13 (Leg.), T8, T10, S16, S17 (2x), S18 (2x), S19, S20 (3x), S21 (2x), Blasius, S22 (Leg.), Dorothea (Leg.), Appolonia (Leg.), S23 (2x), S24 (2x), S25 (Leg.), S28 (3x), Ambrosius (Leg.), Compassio BMV (2x), S29 f., Quirinus (Leg.), S32 f., Pancratius (Leg.), Servatius (Leg.), S42 (Leg.), Erasmus (Leg.), Decem milia martyrum (Leg.), S44 (2x), S46 (3x), Visitatio BMV (2x), \lquote In deportatione BMV\rquote , S47 (Leg.), Divisio apostolorum, S49, Appolinaris, S50, Anna, S52 (2x), S55, S56 (2x), S59 (2x), Helena (Leg.), S61 (3x), S63, S64 (2x), S65 (2x), S66 (2x), Lambertus (2x), S67 (3x), S68 (Leg.), S69 (Leg.), S70 (2x), S71 (Leg.), S72\endash 74, Victor et Gereon (2x), \lquote Sermo qualiter aliquis sit martyr\rquote , S75, S77 (3x), S78 (2x), S79 (2x), S80 (mit Zusatz \lquote In exequiis magnarum personarum\rquote ), Hubertus, S81 (3x), Cunibertus (Leg.), Brictius (Leg.), S82 (Leg.), Praesentatio BMV (3x), S83 (2x), S85 (2x). \endash  Wegen herausgerissener Bl\u228 \'e4tter (s.o.) fehlen: Schluss Apollinaris, Beginn Jacobus (zwischen Bl. 243/244); Schluss Anna, Beginn Panthaleon (zwischen Bl. 249/250); Schluss Sermo secundus de s. Laurentio, Beginn Sermo primus in assumptione BMV (zwischen Bl. 268/269); Beginn Sermo secundus de s. Katharina (zwischen Bl. 447/448). Heiligenpredigten und Predigten zu Weihnachten, Beschneidung, Epiphanias, von Henricus Millingen als Pfarrer in D\u252 \'fcsseldorf gehalten und eigenh\u228 \'e4ndig in vorliegender Hs. f\u252 \'fcr den Eigengebrauch wie auch f\u252 \'fcr weitere Benutzer (vgl. Schlussrubrik 451\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) gesammelt sowie durch Zus\u228 \'e4tze auf den R\u228 \'e4ndern und zwischen den Zeilen erg\u228 \'e4nzt. Dass Henricus seine Predigten zwar lat. aufschrieb, aber dt. hielt (vgl. Landmann S. 107 f.), belegen zahlreiche interlinear nachgetragene dt. \u220 \'dcbersetzungen sowie wiederholt in den Textfluss eingeschobene dt. W\u246 \'f6rter und S\u228 \'e4tze, z.B.: (200\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ; Inventio s. crucis) \plain \f1\i\lang1033\fs26 ... et oraciones sic orando: O domine Ihesu Christe adoro te ... O marteln groit\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 o wonde dyep\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 o kracht de bloitz ...\plain \f1\lang1033\fs26 ; (225\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 , Visitatio BMV, Sermo primus) \plain \f1\i\lang1033\fs26 ... Esurientes implevit bonis \plain \f1\lang1033\fs26 [Lc 1,53] \plain \f1\i\lang1033\fs26 myt syen goitlicke gnade ...\plain \f1\lang1033\fs26 ; vgl. au\u223 \'dferdem gelegentlichen Hinweis, dass nur das Bibelthema lat. vorgelesen wurde (z.B. 400\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 , Beginn des Sermo in die animarum: \plain \f1\i\lang1033\fs26 Charissimi in Christo\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 verba que proposui vobis in Latino\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 accepi ex epistola presentis festivitatis ...\plain \f1\lang1033\fs26 ). \endash  Die Predigten enthalten in der Regel lange Zitate aus der Legenden- und Mirakelliteratur (Legenda aurea, Vincentius Bellovacensis etc.), zu einigen Heiligen finden sich ausschlie\u223 \'dflich Legendentexte (s.o.). D\u252 \'fcsseldorfer Lokalbezug hat die Schilderung von 15 Wundertaten jener Marienstatue (\u8222 \'84nostra imago beate virginis in Duesseldorp\ldblquote  o.\u228 \'e4.; 225\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 227\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 , 307\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 308\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 , 426\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs26 ), die seit alters als \u8222 \'84Maria vom Siege\ldblquote  bekannt ist. Sie befand sich zun\u228 \'e4chst in der Liebfrauenkapelle und nach deren Abriss 1663 in der Kreuzherrenkirche. Seit 1812 ist sie in der Lambertuskirche aufgestellt, vgl. U. Brzosa, Die Geschichte der katholischen Kirche in D\u252 \'fcsseldorf von den Anf\u228 \'e4ngen bis zur S\u228 \'e4kularisation, K\u246 \'f6ln 2001 (Bonner Beitr\u228 \'e4ge zur Kirchengeschichte, 24), S. 241\endash 246, 399\endash 407 (Hs. genannt S. 403\endash 405), 583, Abb. 155. Millingen beschreibt, wie infolge der Verehrung dieser Statue Kranke gesund geworden, Gefangene befreit, Ertrunkene wiederbelebt und Frauen von Geburtsproblemen befreit worden seien; dabei werden genannt: Bilk, Hetterscheidt, \plain \f1\i\lang1033\fs26 Hoickeshage \plain \f1\lang1033\fs26 (Remscheid-Hohenhagen ?), Hottorp, Kamp, Mettmann, Neuss, Sinzig, Stra\u223 \'dfburg, Verona, Wersten; (226\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) ferner Marienbilder in Aachen und Einsiedeln. \endash  Hervorzuheben ist ferner die Einstufung Martin Luthers als H\u228 \'e4retiker, Vorbote des Antichrist und Gesandter des Teufels (9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 , 333\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs26 ; zitiert bei Landmann S. 52, Anm. 2).}

