\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Bl. 51\endash 98: {\field{\*\fldinst HYPERLINK "hida://5130[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Rheinland}}\plain \f1\lang1033\fs22 ; {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 um 1440}}\plain \f1\lang1033\fs22  (nicht lange nach 1437; vgl. Datumsangaben Bl. 52\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs22 ) \u183 \'b7 Papier \u183 \'b7 vier Wz.: (Bl. 51\endash 62) Siebpaar Ochsenkopf; (Bl. 63\endash 98) Siebpaar Traube Gruppe PiccFr I 175\endash 238 (in der Regel zwischen 1440 und 1450) \u183 \'b7 Lagen: 4 VI\plain \f1\super\lang1033\fs24 98\plain \f1\lang1033\fs22  \u183 \'b7 Wassersch\u228 \'e4den (ohne Textverlust) \u183 \'b7 durchgehend Reklamanten \u183 \'b7 Schriftraum 15 x 8,5\endash 9,5 \u183 \'b7 32\endash 36 Zeilen \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 gotische Kursive}}\plain \f1\lang1033\fs22  \u183 \'b7 eine Hand \u183 \'b7 rubriziert.}

