\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 109\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 126\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \plain \f1\scaps\lang1033\fs26 Speculum futurorum temporum\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Speculum futurorum temporum.\plain \f1\lang1033\fs26 < {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Venerabili domine Hildegardi priorisse de sancto Roperto una cum sororibus ibidem deo servientibus Gebenus dictus prior in Everbach licet indignus, inter choros virginum sequi agnum quocumque yerit. Nuper cum essem apud vos, et libellum illum in manibus haberemus}}\plain \f1\i\lang1033\fs26  ... \endash  ... unde ecclesia in eis desolata et quasi vidua est. \plain \f1\lang1033\fs26 \endash  Kompiliert aus \plain \f1\scaps\lang1033\fs26 Hildegardis Bingensis \plain \f1\lang1033\fs26 bzw. aus \plain \f1\scaps\lang1033\fs26 Gebeno Eberbacensis: Speculum futurorum temporum (Pentachronon); \plain \f1\lang1033\fs26 zur Einordnung vgl. C. Meier, Nostris temporibus necessaria. Wege und Stationen der mittelalterlichen Hildegard-Rezeption, in: Architectura poetica. Festschrift f\u252 \'fcr J. Rathofer zum 65. Geburtstag, hg. v. U. Ernst / B. Sowinski, K\u246 \'f6ln/Wien 1990 (K\u246 \'f6lner Germanistische Studien, 30), S. 307\endash 326. Van den Bosch, Speculumliteratur, S. 149, Nr. 50 (diese Hs.). Text der Hs. wie folgt zusammengesetzt: (109\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 116\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Gebeno Eberbacensis}}\plain \f1\scaps\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Speculum futurorum temporum (Pentachronon)}}\plain \f1\scaps\lang1033\fs26 , \plain \f1\lang1033\fs26 Schlussteil\plain \f1\scaps\lang1033\fs26 : \plain \f1\lang1033\fs26 Brief an Priorin und Schwestern des Rupertsbergs sowie Epilog \u8218 \'82De eisdem haereticis ...\rquote . Druck (Ausz\u252 \'fcge): J. B. Pitra (Ed.), Analecta sacra, Bd. 8, Montecassino 1882 (Repr. Farnborough 1966), S. 486\endash 488; zum Inhalt Meier (s.o.) S. 313\endash 315; (117\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Hildegardis Bingensis}}\plain \f1\scaps\lang1033\fs26 :\plain \f1\scaps\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Scivias}}\plain \f1\scaps\lang1033\fs26 , \plain \f1\lang1033\fs26 pars 3, vis. 11, cap. 2\endash 6 (\plain \f1\i\lang1033\fs26 Post incarnacionem \plain \f1\lang1033\fs26 ...). CCCM 43A, S. 578 f.; (117\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 118\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\scaps\lang1033\fs26 Hildegardis Bingensis:\plain \f1\scaps\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Liber divinorum operum}}\plain \f1\scaps\lang1033\fs26 , \plain \f1\lang1033\fs26 pars 3, vis. 5, cap. 16 (\plain \f1\i\lang1033\fs26 Primum tempus ...\plain \f1\lang1033\fs26 ). CCCM 92, S. 433\endash 436; (118\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 119\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\scaps\lang1033\fs26 Hildegardis Bingensis:\plain \f1\scaps\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Epistola}}\plain \f1\scaps\lang1033\fs26  \plain \f1\scaps\lang1033\fs26 (15\plain \f1\lang1033\fs26 R) \plain \f1\scaps\lang1033\fs26 ad pastores