\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Bl. 6\endash 114: Rheinland; 9. Jh., 3. Drittel \u183 \'b7 Lagen: (III+1)\plain \f1\super\lang1033\fs24 12\plain \f1\lang1033\fs22  + 3 IV\plain \f1\super\lang1033\fs24 36\plain \f1\lang1033\fs22  + (III+1)\plain \f1\super\lang1033\fs24 43\plain \f1\lang1033\fs22  + 2 IV\plain \f1\super\lang1033\fs24 59 \plain \f1\lang1033\fs22  + (III+2)\plain \f1\super\lang1033\fs24 67\plain \f1\lang1033\fs22  + 2 IV\plain \f1\super\lang1033\fs24 83\plain \f1\lang1033\fs22  + (III+2)\plain \f1\super\lang1033\fs24 91\plain \f1\lang1033\fs22  + 2 IV\plain \f1\super\lang1033\fs24 107\plain \f1\lang1033\fs22  + (II+3)\plain \f1\super\lang1033\fs24 114\plain \f1\lang1033\fs22  \u183 \'b7 Bl. 114 zeitweilig als R\u252 \'fcckspiegel verklebt \u183 \'b7 Schlussseite Lage 2 eingekreiste Lagenz\u228 \'e4hlung:\plain \f1\i\lang1033\fs22  II\plain \f1\lang1033\fs22  \u183 \'b7 Schriftraum 20\endash 21 x 12\endash 13 \u183 \'b7 25\endash 26 Zeilen \u183 \'b7 karolingische Minuskel; \u220 \'dcberschriften anfangs in Capitalis rustica, danach in gemischter Capitalis und Unziale \u183 \'b7 drei H\u228 \'e4nde (A: 6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 29\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 , 30\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 51\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ; B: 29\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 30\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ; C: 52\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \endash 113\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ); Oratio 114\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  Nachtragsschreiber, trotz des gr\u246 \'f6beren Duktus identisch mit Nachtragsschreiber 4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  (?; vgl. Teil I) \u183 \'b7 \u220 \'dcberschriften und Z\u228 \'e4hlziffern in Rot; 2\endash 3-zeilige rote und braune Capitalis-Initialen; anf\u228 \'e4nglich zumeist in Braun, rot gef\u252 \'fcllt und stellenweise mit Rankenausl\u228 \'e4ufern.}

