\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 1998 restauriert \u183 \'b7 Lagen: Bl. 1\plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs22  + 21 IV\plain \f1\super\lang1033\fs24 169\plain \f1\lang1033\fs22  + Bl. 170\plain \f1\super\lang1033\fs24 170\plain \f1\lang1033\fs22  \u183 \'b7 ehemaliger Pergament-Vorderspiegel zeitweise lose einliegend, nicht mitfoliiert, bei Restaurierung erg\u228 \'e4nzt und vor Bl. 1 freistehend eingebunden \u183 \'b7 unterer Rand Bl. 85, 122, 127 ohne Textverlust herausgeschnitten \u183 \'b7 im oberen Bereich zahlreicher Textspalten fortschreitender, teils bereits erheblicher Textverlust durch abbl\u228 \'e4tternde Tinte; 1\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs22 , 170\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs22  stellenweise Textverlust durch Abrieb \u183 \'b7 Lage 1\endash 20 Lagenz\u228 \'e4hlung:\plain \f1\i\lang1033\fs22  I\endash XX\plain \f1\lang1033\fs22  \u183 \'b7 Schriftraum 24 x 18; 169\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22 \endash 170\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs22 , 1\plain \f1\super\lang1033\fs24 ra\endash vb\plain \f1\lang1033\fs22  24,5\endash 29,5 x 19\endash 21 \u183 \'b7 zwei Spalten \u183 \'b7 35 Zeilen; 169\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22 \endash 170\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs22 , 1\plain \f1\super\lang1033\fs24 ra\endash vb\plain \f1\lang1033\fs22  44\endash 56 Zeilen \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 karolingische Minuskel}}\plain \f1\lang1033\fs22  \u183 \'b7 ein Hauptschreiber; ein Nachtragsschreiber (169\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22 \endash 170\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs22 , 1\plain \f1\super\lang1033\fs24 ra\endash vb\plain \f1\lang1033\fs22 ) \u183 \'b7 rubriziert; Rubrikatorvorgaben an den R\u228 \'e4ndern; 7\endash 12-zeilige rote {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Silhouetteninitialen}}\plain \f1\lang1033\fs22 .}

