\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 2002 restauriert \u183 \'b7 Lagen: 9 V\plain \f1\super\lang1033\fs24 90\plain \f1\lang1033\fs22  + III\plain \f1\super\lang1033\fs24 96\plain \f1\lang1033\fs22  + 18 V\plain \f1\super\lang1033\fs24 276\plain \f1\lang1033\fs22  + (III+2)\plain \f1\super\lang1033\fs24 284\plain \f1\lang1033\fs22  + III\plain \f1\super\lang1033\fs24 290\plain \f1\lang1033\fs22  + 4 V\plain \f1\super\lang1033\fs24 330\plain \f1\lang1033\fs22  + VI\plain \f1\super\lang1033\fs24 342\plain \f1\lang1033\fs22  \u183 \'b7 ehemalige Spiegel heute freistehend, modern foliiert:\plain \f1\i\lang1033\fs22  I\plain \f1\lang1033\fs22 ;\plain \f1\i\lang1033\fs22  343\plain \f1\lang1033\fs22  \u183 \'b7 jeweils auf erster und letzter Lagenseite Lagenz\u228 \'e4hlung:\plain \f1\i\lang1033\fs22  I\plain \f1\lang1033\fs22 ,\plain \f1\i\lang1033\fs22  II\plain \f1\i\super\lang1033\fs24 us \plain \f1\i\lang1033\fs22 ... XXXV\plain \f1\lang1033\fs22 ; teilweise Reklamanten; ab Lage 3 Doppelblattz\u228 \'e4hlung (Bleistift):\plain \f1\i\lang1033\fs22  I\endash V\plain \f1\lang1033\fs22  etc. \u183 \'b7 auf den oberen Seitenr\u228 \'e4ndern Rubrikatorvorgaben und Spaltenz\u228 \'e4hlung (Bleistift) \u183 \'b7 Schriftraum 24,5\endash 25 x 15,5,\endash 16,5 \u183 \'b7 zwei Spalten \u183 \'b7 35\endash 36 Zeilen; 342\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22 \endash 343\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22  37 bzw. 30 Zeilen \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 gotische Textualis}}\plain \f1\lang1033\fs22  \u183 \'b7 drei Hauptschreiber (A: 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22 \endash 30\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22 ; B: 30\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22 \endash 284\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs22 , 291\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22 \endash 342\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22 ; C: 285\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22 \endash 290\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs22 ; 342\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22 \endash 343\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22  ein Nachtragsschreiber \u183 \'b7 rubriziert; Seitentitel in Rot; 2\endash 5-zeilige rote, stellenweise ornamental gespaltene Lombarden.}

