\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Bl. 121\endash 160: {\field{\*\fldinst HYPERLINK "hida://5130[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 n\u246 \'f6rdl. Rheinland}}\plain \f1\lang1033\fs22  (Marienfrede, Kreuzherrenkonvent?); {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 15. Jh., Mitte}}\plain \f1\lang1033\fs22  \u183 \'b7 Wz.: Siebpaar Ochsenkopf \u183 \'b7 Lagen: 2 VI\plain \f1\super\lang1033\fs24 144\plain \f1\lang1033\fs22  + VIII\plain \f1\super\lang1033\fs24 160\plain \f1\lang1033\fs22  \u183 \'b7 durchgehend Reklamanten \u183 \'b7 Schriftraum 15 x 9,5 \u183 \'b7 33 Zeilen \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 gotische Kursive}}\plain \f1\lang1033\fs22  \u183 \'b7 eine Hand \u183 \'b7 rubriziert \u183 \'b7 Schreibsprache: {\field{\*\fldinst HYPERLINK "hida://5710[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 mittelniederl\u228 \'e4ndisch}}\plain \f1\lang1033\fs22  (Reichling S. 90: niederfr\u228 \'e4nkische Grundlage).}

