\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 106\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 \endash 108\plain \f1\super\lang1033\fs24 vb\plain \f1\scaps\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Thomas de Aquino}}\plain \f1\scaps\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Commentum in quartum librum sententiarum}}\plain \f1\scaps\lang1033\fs26 . \plain \f1\lang1033\fs26 Exzerpte zum Thema \lquote confessio\rquote \plain \f1\scaps\lang1033\fs26 : \plain \f1\i\lang1033\fs26 Thomas in sentenciis de confessione. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Quidquid potest inferior potest superior, sed ipse sacerdos potest}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 [d. 17, q. 3, a. 3; Frett\u233 \'e9/Mar\u233 \'e9, s.u., S. 508a, Z. 17 ff.] \plain \f1\i\lang1033\fs26 ... \endash  ... \plain \f1\lang1033\fs26 [bricht ab in d. 19, q. 2, a. 2; Frett\u233 \'e9/Mar\u233 \'e9, s.u., S. 558b, Z. 31] \plain \f1\i\lang1033\fs26 vel de medio subtrahat. Unde \plain \f1\scaps\lang1033\fs26 \u9553 \'a6 \plain \f1\scaps\lang1033\fs26 \endash  \plain \f1\scaps\lang1033\fs26 D\plain \f1\lang1033\fs26 ruck des Grundtextes: S. E. Frett\u233 \'e9 / P. Mar\u233 \'e9 (Hg.), Doctoris angelici divi Thomae Aquinatis ... opera omnia, Bd. 10, Paris 1873\plain \f1\scaps\lang1033\fs26 ; \plain \f1\lang1033\fs26 Exzerpte der Hs. in folgender Reihenfolge: aus d. 17, q. 3, a. 3 f.; (d. 2, q. 1, a. 1); d. 9, q. 1, a. 3; d. 13, q. 1, a. 1; d. 12, q. 3, a. 1; d. 12, q. 2, a. 2; d 13, q. 1, a. 2; d. 19, q. 2, a. 2; d. 38, q. 1, a. 1\endash 4; d. 19, q. 2, a. 2; Textl\u252 \'fccke zwischen (106\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 ; bricht ab in d. 2, q. 1, a. 1; Frett\u233 \'e9/Mar\u233 \'e9, s.o., S. 47a, Z. 14) und (107\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ; setzt ein in d. 9, q. 1, a. 3; Frett\u233 \'e9/Mar\u233 \'e9, s.o., S. 219a, Z. 26) belegt, dass das urspr\u252 \'fcngliche innere Doppelbl. der vorliegenden Schlusslage fehlt (hier Ternio statt wie in der \u252 \'fcbrigen Hs. Quaternionen)\plain \f1\scaps\lang1033\fs26 . \plain \f1\lang1033\fs26 Stegm\u252 \'fcller RS Nr. 846 (IV)\plain \f1\scaps\lang1033\fs26 . \plain \f1\lang1033\fs26 Michelitsch S. 63 (Hs. genannt).}

