\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 254\plain \f1\super\lang1033\fs24 va\endash b\plain \f1\scaps\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 De bono et malo homine}}\plain \f1\scaps\lang1033\fs26 . \plain \f1\lang1033\fs26 (254\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 )\u9553 \'a6 \plain \f1\i\lang1033\fs26 Dilectus deo et hominibus est cuius memoria in \plain \f1\lang1033\fs26 \u9553 \'a6 [Zeile 2:] \plain \f1\i\lang1033\fs26 erit. Ad hominem talem pertinet bonitas ... \endash  ... \plain \f1\lang1033\fs26 (254\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 delectacio finitur peccato peracto. \plain \f1\lang1033\fs26 \endash  Textverlust wegen Blattbesch\u228 \'e4digung.}

