\par \pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 Bl. 175\endash 232: {\field{\*\fldinst HYPERLINK "hida://5130[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Westdeutschland}}\plain \f1\lang1033\fs22 ; {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 um 1410/20}}\plain \f1\lang1033\fs22  \u183 \'b7 Wz.: Dreiberg ~ PiccDr II 708 (1413); drei Ochsenk\u246 \'f6pfe Typ PiccO VIII 51 (1411\endash 1416); Typ PiccO VIII 75 (1411\endash 1416) (?); Typ PiccO IX 21\endash 30 (1409\endash 1416) \u903 ? Lagen: 4 VI\plain \f1\super\lang1033\fs24 222 \plain \f1\lang1033\fs22  + V\plain \f1\super\lang1033\fs24 232\plain \f1\lang1033\fs22  \u183 \'b7 Reklamanten der Schreiberhand (Bl. 186, 198, 210, 222) \u183 \'b7 moderne Foliierung in Bleistift \u183 \'b7 Schriftraum 14,5\endash 15 x 9,5\endash 10 \u183 \'b7 22\endash 27 Zeilen \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 gotische Kursive}}\plain \f1\lang1033\fs22 ; Fabelanf\u228 \'e4nge in vergr\u246 \'f6\u223 \'dferter {\field{\*\fldinst HYPERLINK "hida://5704[1]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Textualis}}\plain \f1\lang1033\fs22  \u183 \'b7 eine Hand; von einer sp\u228 \'e4teren Hand (17./18. Jh.) nachgetragene Marginalien (stichwortartige Notizen zur Fabellehre, teilweise in Form von Sprichw\u246 \'f6rtern) in Tinte und Bleistift mit einer Ausnahme (190\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ) in lat. Sprache \u183 \'b7 rubriziert; 2-zeilige rote Lombarden.}

