\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 17\plain \f1\super\lang1033\fs24 r\plain \f1\scaps\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Dicta et excerpta de communione et celebratione missae}}\plain \f1\scaps\lang1033\fs26 . 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 (13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 14\plain \f1\super\lang1033\fs24 r\plain \f1\scaps\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Nota propter quid sit libenter communicandum.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Unaqueque fidelis anima libenter ac desiderantissime debet communicari}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 armis et victualibus muniuntur contra hostes\plain \f1\lang1033\fs26 ; anschlie\u223 \'dfend: \plain \f1\i\lang1033\fs26 Venerabilis presbiter {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Beda}}\plain \f1\i\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Sacerdos, qui sine peccato mortali est et in bono proposito, si non celebrat missam}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 in purgatorio iacentes subventione privat et venia. \plain \f1\lang1033\fs26 (14\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 David de Augusta}}\plain \f1\scaps\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 De exterioris et interioris hominis compositione}}\plain \f1\scaps\lang1033\fs26 ], \plain \f1\lang1033\fs26 lib. 3, cap. 70. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Si aliquis desiderat experiri, utrum sit melius sepius an rarius corporis Cristi suscipere sacramentum}}\plain \f1\i\lang1033\fs26  ... \endash  ... causarum ratione solet illud evenire. \plain \f1\lang1033\fs26 CALMA Bd. 3,1, S. 66 f., Nr. 1. Distelbrink Nr. 86; vgl. T. Hohmann, Initienregister der Werke Heinrichs von Langenstein, S. 418, Nr. 214, in: Traditio 32 (1976), S. 399\endash 426; Madre S. 291; J. Lang, Die Christologie bei Heinrich von Langenstein, Freiburg (u.a.) 1966 (Freiburger theologische Studien, 85), S. 53. Franz, Messe, S. 521 f. (16\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Item. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Circa sacerdotes potest hec forma teneri}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 pluribus locis reperiuntur. \plain \f1\lang1033\fs26 (16\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 De diversis affectionibus, quibus trahimur ad communicandum vel celebrandum\plain \f1\lang1033\fs26 .\plain \f1\i\lang1033\fs26 < {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Diversis affectibus et intentionibus diversi ad communicandum trahuntur vel ad celebrandum}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 et semper interpellat pro nobis. Item. Omnia, que orantes petimus, sunt ista: aut oramus pro malis, que fecimus, ignoscendis \u8230 \'85 \endash  \u8230 \'85 aut cum gratias agimus pro acceptis vel promissis. \plain \f1\lang1033\fs26 \endash  Druck: Fr. David ab Augusta O.F.M., De exterioris et interioris hominis compositione, Quaracchi 1899, S. 374\endash 378 (stellenweise abweichend). (17\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 23\plain \f1\super\lang1033\fs24 v\plain \f1\scaps\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Examinatio consciencie\plain \f1\lang1033\fs26 .< {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Ad hoc, quod aliquis digne ad sacramentum corporis Christi sumendum accedat, requiritur examinatio conscientie}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 Tertium est gratiarum actio pro accepto beneficio\plain \f1\lang1033\fs26 . Vgl. Mohan, Initia, S. 298 (Primo requiritur examinatio conscientiae ...).}

