\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs26 Augustinus: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Assit affectus orantis}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \plain \f1\lang1033\fs26 (111\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Item. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Bonus et strenuus miles non vadit cum uxore sua}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \plain \f1\lang1033\fs26 Genannte Quellen: {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Bernardus}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 philosophus\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Regula S. Benedicti}}\plain \f1\lang1033\fs26 . (112\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 )  {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Ancelmus}}\plain \f1\i\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 In scriptura sacra res una et eiusdem locutionis invenitur}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85qui nos non urat per diem\plain \f1\lang1033\fs26 . (112\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 )  {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Ad virtutes verbis et exemplis provocamur}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \plain \f1\lang1033\fs26 Schlie\u223 \'dft mit [Io 13,15]; darunter:\plain \f1\i\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Augustinus}}\plain \f1\i\lang1033\fs26 . {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Malivole anime dulciter sapit, quod pessime suspicatur}}\plain \f1\lang1033\fs26 . {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Sermones}}\plain \f1\lang1033\fs26 , PL 39, Sp. 1564. (113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 114\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Bernardus de devotione\plain \f1\lang1033\fs26 .< {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Querat devocionis gratiam}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 sed in mira dilatatione commorantur\plain \f1\lang1033\fs26 . Kompilation aus verschiedenen Sermones. Leclercq/Rochais Bd. 4, S. 248 ff.; Bd. 5, S. 136. (114\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) {\field{\*\fldinst HYPERLINK "hida://bezper[4].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Ambrosius}}\plain \f1\i\lang1033\fs26 in libro {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 de virginitate}}\plain \f1\i\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Omnia nobis Cristus factus est. Si vulnus curare desideras}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \plain \f1\lang1033\fs26 PL 16, Sp. 305;\plain \f1\i\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[5].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Ubertinus}}\plain \f1\i\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Desiderat cervus fontem, cecus lumen, afflictus pacem}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 desiderat anima sancta deum; \plain \f1\lang1033\fs26 direkt angeschlossen: \plain \f1\i\lang1033\fs26 Unde Augustinus: {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Fecisti nos, domine, ad te}}\plain \f1\i\lang1033\fs26  \u8230 \'85\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Confessiones}}\plain \f1\lang1033\fs26 , CC 27, S. 1, Z. 6 f.; (115\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) Ps 4,7 und Ps 103,24 mit kurzen Kommentaren (darin erw\u228 \'e4hnt Metaphysica von Aristoteles). (115\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 116\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Bernardus: {\field{\*\fldinst HYPERLINK "hida://5650[10].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Periclitatur in deliciis castitas}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 gratia fert auxilium. \plain \f1\lang1033\fs26 Leclercq/Rochais Bd. 4, S. 113, Z. 14 \endash S. 114, Z. 8. \plain \f1\i\lang1033\fs26 Idem. {\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Quam pauci post te, o domine, ire volunt}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 sed non compati. Non curant querere, quem tamen desiderant invenire\plain \f1\lang1033\fs26 . Ebd. Bd. 1, S. 123, Z. 6\endash 9; Z. 15 f. Weitere Initien im Register.}

