\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 117\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 118\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26  \plain \f1\scaps\lang1033\fs26 Excerpta varia.\plain \f1\i\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Eternus deus, eterni dei filius dominus noster Ihesus Christus creator omnium rerum}}\plain \f1\i\lang1033\fs26  ... \endash  \plain \f1\lang1033\fs26 (117\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 ... numquam finiendi particeps fiat? \plain \f1\lang1033\fs26 Conradus Eberbacensis, Exordium Magnum Cisterciense 1, 1, Z. 5\endash 23, CCCM 138, S. 5 f. \plain \f1\i\lang1033\fs26 Bernardus: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Utraque cognitio videlicet boni et mali}}\plain \f1\i\lang1033\fs26  ... \plain \f1\lang1033\fs26 Vgl. Leclercq/Rochais Bd. 2, S. 8, Z. 8 ff.; \plain \f1\i\lang1033\fs26 Augustinus: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Excercete }}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 [!]}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17  bellum, sperate triumphum}}\plain \f1\lang1033\fs26 . Sermones, PL 38, Sp. 719. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Spera, persevera, sustine: salvaberis}}\plain \f1\i\lang1033\fs26 . \plain \f1\lang1033\fs26 Dieser Spruch auch auf Bl. 86\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 . (118\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Augustinus ad Cristinum: {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 In itinere dei}}\plain \f1\i\lang1033\fs26  ... \plain \f1\lang1033\fs26 Augustinus, Epistolae, PL 33, Sp. 1071; \plain \f1\i\lang1033\fs26 Hugo: {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Hoc est ad deum tendere}}\plain \f1\i\lang1033\fs26  \u8230 \'85\plain \f1\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hugo de Sancto Victore}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De archa Noe}}\plain \f1\lang1033\fs26 , CCCM 176, S. 28, Z. 119\endash 122; Ps. [118,20]: {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Concupivit anima \u8230 \'85 Non potuit saciari}}\plain \f1\i\lang1033\fs26  \u8230 \'85 {\field{\*\fldinst HYPERLINK "hida://bezper[4].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Richardus de Sancto Victore}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De gradibus caritatis}}\plain \f1\lang1033\fs26 , PL 196, Sp. 1200, 1203.}

