\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 146\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 146\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \plain \f1\scaps\lang1033\fs26 [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Guilelmus de Sancto Theodorico}}\plain \f1\scaps\lang1033\fs26 ]: {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Epistola ad fratres de monte Dei}}\plain \f1\scaps\lang1033\fs26 , \plain \f1\lang1033\fs26 Exzerpt\plain \f1\scaps\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Bernardus ad fratres de monte dei xxii capitulo. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Certis horis certe lectioni vacandum est}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \plain \f1\lang1033\fs26 \endash  \plain \f1\i\lang1033\fs26 \u8230 \'85 coaptantur \plain \f1\lang1033\fs26 (recte: cooperantur) \plain \f1\i\lang1033\fs26 ei in bonum etc. \plain \f1\lang1033\fs26 \endash  Ed.: CCCM 88, S. 225\endash 289, hier 253 f. (par. 120\endash 124). Literatur vgl. bei Ms. B 156.}

