\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 81\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 87\plain \f1\super\lang1033\fs24 r\plain \f1\scaps\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Compendium fidei}}\plain \f1\lang1033\fs26 , mit Merkversen \plain \f1\i\lang1033\fs26 >Notandum quod hec sequuntur a quolibet fideli christiano scienda sunt et servanda sine quibus nulli omnino et salus. Primo oratio dominica septem continens peticiones, in quibus omnia saluti necessaria sufficientissime includuntur.< \plain \f1\lang1033\fs26 Es folgen: (82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Captatio benivolencie \plain \f1\lang1033\fs26 (\plain \f1\i\lang1033\fs26 Pater noster\plain \f1\lang1033\fs26 ), \plain \f1\i\lang1033\fs26 Salutatio angelica \plain \f1\lang1033\fs26 (\plain \f1\i\lang1033\fs26 Ave Maria\plain \f1\lang1033\fs26 ); >\plain \f1\i\lang1033\fs26 De duodecim articulis catholice fidei secundum duodecim apostolos. Nos enim articulos fidei non solum sacerdotes et clerici, sed eciam layci debent scire, quia ista est substancia fidei christiane, quod si quis in uno peccaret non credendo et ceteros crederet, infidelis esset\plain \f1\lang1033\fs26 .< Es folgt Symbolum; (82\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 83\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Decem praecepta antique legis\plain \f1\lang1033\fs26 ; (83\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 84\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 Explanatio quedam decem preceptorum.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Hec decem precepta strictissime mandavit dominus observari non sub obtentu oculorum}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \plain \f1\lang1033\fs26 (84\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Septem sacramenta nove legis\plain \f1\lang1033\fs26 , >\plain \f1\i\lang1033\fs26 Septem sunt opera misericordie corporalia, que patent in hoc versu:< \plain \f1\lang1033\fs26 (85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 )\plain \f1\i\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Visito, poto, cibo, redimo, tego, colligo, condo}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 (Walther I Nr. 20647; Walther II Nr. 33805, Vers 1); >\plain \f1\i\lang1033\fs26 Sex sunt opera misericordie spiritualia, que patent in hoc versu:< {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Consule, castiga, solare, remitte, fer, ora}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 (Walther II Nr. 3235); (85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Septem dona spiritus sancti\plain \f1\lang1033\fs26 ; \plain \f1\i\lang1033\fs26 Octo beatitudines, quas Christus dominus cum suis premiis enuerat\plain \f1\lang1033\fs26 ; \plain \f1\i\lang1033\fs26 Tres virtutes theologice\plain \f1\lang1033\fs26 ; \plain \f1\i\lang1033\fs26 Quatuor virtutes cardinales\plain \f1\lang1033\fs26 ; (85\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Duodecim fructus spiritus; Quinque sensus corporis; Septem bona anime; Septem bona corporis; >Novem sunt peccata aliena, que patent in hijs versibus:< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Jussio, consilium, consensus, palpe, recursus}}\plain \f1\i\lang1033\fs26  / Participans, mutus, non obstans, non manifestans \plain \f1\lang1033\fs26 (Walther I Nr. 9990); \plain \f1\i\lang1033\fs26 Sex species peccati in spiritum sanctum\plain \f1\lang1033\fs26 ; >\plain \f1\i\lang1033\fs26 Quatuor sunt genera peccatorum, que clamant ad deum pro vindicam:< {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Clamitant in celis vox sanguinis et sodomorum vox oppressorum, merces retenta servorum}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 (Walther I Nr. 2821; vgl. Walther II Nr. 2786); (85\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 87\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Septem peccata mortalia\plain \f1\lang1033\fs26 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 87\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 90\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \plain \f1\scaps\lang1033\fs26 Meditationes, dicta et auctoritates de morte. \plain \f1\lang1033\fs26 (87\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 88\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\scaps\lang1033\fs26 [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Gerardus de Zutphania}}\plain \f1\scaps\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 De spiritualibus ascensionibus}}\plain \f1\scaps\lang1033\fs26 ]\plain \f1\lang1033\fs26 , cap. 19. \plain \f1\i\lang1033\fs26 >Sequuntur hic quatuor novissima sub compendio excitativa timoris, compunctionis et amoris. Generalis modus ad formandum meditaciones de morte.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Memorare novissima \u8230 \'85 }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 [Sir 7,40]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 . Meditare igitur homo et ab oculis tuis numquam recedat }}\plain \f1\i\lang1033\fs26 \u8230 \'85 \endash  \u8230 \'85 et nichil hic viciose dilexit. \plain \f1\lang1033\fs26 \endash  Ed.: F. J. Legrand (Hg.), G\u233 \'e9rard Zerbolt de Zutphen: La mont\u233 \'e9e du c\u339 \'9cur (De spiritualibus ascensionibus), Turnhout 2006 (Sous la r\u232 \'e8gle de Saint Augustin, 11), S. 160\endash 167. Zu Verfasser und Werk vgl. VL\plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26  Bd. 10, Sp. 1537\endash 1541; K. Ruh, Geschichte der abendl\u228 \'e4ndischen Mystik, Bd. 4, M\u252 \'fcnchen 1999, S. 165\endash 173, bes. S. 170\endash 173. Weitere Literaturangaben in der Beschreibung zu Ms. B 129; anschlie\u223 \'dfend \plain \f1\i\lang1033\fs26 >Auctoritates de morte.< \plain \f1\lang1033\fs26 Sir 41,1\endash 2; Sir 41,5; Bar 3,16\endash 19. (89\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\scaps\lang1033\fs26 [Ps.-]{\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Bernardus Claraevallensis}}\plain \f1\scaps\lang1033\fs26 : [{\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Meditationes de cognitione humanae conditionis}}\plain \f1\scaps\lang1033\fs26 ]\plain \f1\lang1033\fs26 , Exzerpt. \plain \f1\i\lang1033\fs26 Unde Bernardus: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Dic michi, ubi sunt amatores mundi}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 quia homo es\plain \f1\lang1033\fs26 . PL 184, Sp. 491. Angaben zum Text vgl. Beschreibung zu Ms. B 132, 168\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 . (89\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs26 ) \plain \f1\scaps\lang1033\fs26 [Ps.-{\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Cyrillus Hierosolymitanus}}\plain \f1\scaps\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Epistola ad Augustinum de miraculis Hieronymi}}\plain \f1\scaps\lang1033\fs26 ]\plain \f1\lang1033\fs26 , Exzerpte. \plain \f1\i\lang1033\fs26 >In obitu beati Jheronimi de horribili visione demonum in morte.< {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Die, quo moriturus erat venerabilis Eusebius, beati Jheronimi discipulus}}\plain \f1\i\lang1033\fs26  ... \endash  \plain \f1\lang1033\fs26 (89\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 ... velut fumus ab eo evanuit\plain \f1\lang1033\fs26 . PL 22, Sp. 292 f. und PL 33, Sp. 1128 f. \plain \f1\i\lang1033\fs26 >Quedam revelacio de penis inferni.< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Unus ex tribus mortuis}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  ... nec tantas cogitant evadere penas\plain \f1\lang1033\fs26 . PL 22, Sp. 293 f. und PL 33, Sp. 1129 f. CPL Nr. 367; BHL Nr. 3868; CPPM Bd. 2, Nr. 145 (19). (89\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 90\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 >De penitencia Mauricii imperatoris.< {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Sed prudens imperator Mauricius hec considerans pocius petivit hic pro peccatis }}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 (90}}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 ) }}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 puniri quam ibi}}\plain \f1\i\lang1033\fs26  \plain \f1\i\lang1033\fs26 \u8230 \'85 \endash  \u8230 \'85 ita ut inspicientes flerent\plain \f1\lang1033\fs26 . Vgl. Johannes Hymmonides, Vita S. Gregorii Magni, AASS, M\u228 \'e4rz, Bd. 2, S. 184 und PL 75, Sp. 183 ff. (90\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 >Exemplum de quodam duce Burgundie.< {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Cum quidam dux Burgundie corpus patris sui vellet transferre aperto sepulchro}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \plain \f1\lang1033\fs26 \endash  (90\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 \u8230 \'85 unde infra terminum constitutum deficiunt\plain \f1\lang1033\fs26 .}

