\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 179\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 \endash 192\plain \f1\super\lang1033\fs24 vb\plain \f1\scaps\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Petrus Aureoli}}\plain \f1\scaps\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Tractatus de conceptione BMV}}\plain \f1\scaps\lang1033\fs26 . \plain \f1\lang1033\fs26 >\plain \f1\i\lang1033\fs26 In nomine unigeniti Marie virginis. Incipit tractatus de concepcione eiusdem immolate Marie editus a fratre Petro Aureoli.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Nondum erant abissi \u8230 \'85 }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 [Prv 8,24]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 . De concepcione virginis tractaturi, que se videtur innuere }}\plain \f1\i\lang1033\fs26 \u8230 \'85 \plain \f1\lang1033\fs26 \endash  \plain \f1\i\lang1033\fs26 ... quoniam sola ipsa capud fidei et catholice veritatis a Christo constituta est. Qui cum patre et spiritu sancto vivit et regnat. Amen. \endash \plain \f1\lang1033\fs26 Ed.: G. Guarra, Quaestiones disputatae de immaculata conceptione beatae Mariae virginis, Quaracchi 1904 (Bibliotheca Franciscana scholastica medii aevi, 3), S. 23\endash 94. Glorieux, R\u233 \'e9pertoire, Nr. 351c.}

