\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 138\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 \endash 177\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26  \plain \f1\scaps\lang1033\fs26 [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Johannes Blomendal}}\plain \f1\scaps\lang1033\fs26 ]\plain \f1\scaps\lang1033\fs26 :\plain \f1\scaps\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Postillae evangeliorum de sanctis}}\plain \f1\lang1033\fs26 . 42 St\u252 \'fccke (Siglen nach Schneyer): S1,8; T5,6 (3 St\u252 \'fccke); S9\endash 11,13; T8,10,11; S17,18,20\endash 25,28,30,32,33,44\endash 46; octava beatorum apostolorum; septem fratres; S49,50,56,59,61,64\endash 67,70,79; C11 (Initien im Register). >\plain \f1\i\lang1033\fs26 De sancto Andrea.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Ambulans Ihesus \u8230 \'85 }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 [Mt 4,18]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 . Hic describitur apostolorum vocatio, ut quia Ihesus volebat facere et docere}}\plain \f1\i\lang1033\fs26  \plain \f1\i\lang1033\fs26 \u8230 \'85\plain \f1\lang1033\fs26 ; (139\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 \endash 139\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 >De beato Thoma apostolo.< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Thomas autem unus \u8230 \'85 }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 [Io 20,24\endash 25]}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 . Autem ponitur hic resurrectionis annunciatio absenti discipulo}}\plain \f1\i\lang1033\fs26  \plain \f1\i\lang1033\fs26 \u8230 \'85\plain \f1\lang1033\fs26 ; (139\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 \endash 141\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 >In vigilia nativitatis Christi.< {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Cum esset desponsata \u8230 \'85 }}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 [Mt 1,18]}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 . Ne aliquis crederet generacionem Christi fuisse ex commixtione viri et mulieris}}\plain \f1\i\lang1033\fs26  \plain \f1\i\lang1033\fs26 \u8230 \'85\plain \f1\lang1033\fs26 ; (173\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 \endash 175\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 In festo sancti Mychaelis.< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Accesserunt ad Ihesum \u8230 \'85 }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 [Mt 18,1\endash 4]}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 . Hic agitur de fundamento ponendo in moribus, quod est humilitas}}\plain \f1\i\lang1033\fs26  \plain \f1\i\lang1033\fs26 \u8230 \'85\plain \f1\lang1033\fs26 ; (175\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs26 \endash 176\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 >In festo omnium sanctorum.< \plain \f1\i\lang1033\fs26\chcbpat17 Videns Ihesus \u8230 \'85 {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 [Mt 5,1\endash 3]}}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 . Hic agitur de lacione nove legis per Christum}}\plain \f1\i\lang1033\fs26  \plain \f1\i\lang1033\fs26 \u8230 \'85\plain \f1\lang1033\fs26 ; letzte Predigt: (176\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs26 \endash 177\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs26 ) >\plain \f1\i\lang1033\fs26 In dedicacione ecclesie.< {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Egressus Ihesus \u8230 \'85 }}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 [Lc 19,1\endash 4]}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 . Hic agitur de conversione peccatorum in speciali et specialiter ipsius Zachei}}\plain \f1\i\lang1033\fs26  \plain \f1\i\lang1033\fs26 \u8230 \'85 \endash  \u8230 \'85 et salvetur per eternam gloriam. Amen\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 >Expliciunt postille pauperum super ewangelia de sanctis per circulum anni complete sub annis domini 1475\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs26 .< \plain \f1\lang1033\fs26 \endash  Diese Predigtsammlung wird ebenfalls Theodoricus Bollick zugeschrieben. Vgl. dazu Landmann S. 80, Anm. 3 (Hs. genannt); Schneyer, Wegweiser, S. 19 (diese Hs.). Zu Johannes Blomendal vgl. die Beschreibung zu Ms. B 110. Die meisten Texte sind auch dort \u252 \'fcberliefert (au\u223 \'dfer S8,24,25, octava beatorum apostolorum, S61).}

