\par \pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 Bl. 3\endash 66: {\field{\*\fldinst HYPERLINK "hida://5130[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Niederrhein}}\plain \f1\lang1033\fs22 ; {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 15. Jh., Mitte}}\plain \f1\lang1033\fs22  \u183 \'b7 Wz.: Hammer Gruppe PiccWW I 88\endash 104 (1427\endash 1451) und Gruppe PiccWW I 118\endash 120 (1448, 1449), auch in Teil III; wegen der Besch\u228 \'e4digung der Hs. durch Tintenfra\u223 \'df ist die Bestimmung aller Wz. nicht m\u246 \'f6glich \u183 \'b7 Lagen: IV\plain \f1\super\lang1033\fs24 10\plain \f1\lang1033\fs22  + 7 IV\plain \f1\super\lang1033\fs24 66\plain \f1\lang1033\fs22  \u183 \'b7 Lagensignaturen: <\plain \f1\i\lang1033\fs22 a1\plain \f1\lang1033\fs22 >\endash <\plain \f1\i\lang1033\fs22 a4\plain \f1\lang1033\fs22 > \u8230 \'85\plain \f1\i\lang1033\fs22  h1\plain \f1\lang1033\fs22 \endash \plain \f1\i\lang1033\fs22 h4\plain \f1\lang1033\fs22  \u183 \'b7 moderne Foliierung in Bleistift (\plain \f1\i\lang1033\fs22 3\endash 66\plain \f1\lang1033\fs22 ) \u183 \'b7 Schriftraum 9,7\endash 10 x 6,5 \u183 \'b7 19\endash 25 Zeilen \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 gotische Hybrida}}\plain \f1\lang1033\fs22  \u183 \'b7 zwei H\u228 \'e4nde (A: 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \endash 5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ; B: 6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \endash 63\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 , Hand B auch in Teilen III und V) \u183 \'b7 rubriziert; 2\endash 4-zeilige (gespaltene) rote Lombarden; 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 : 4-zeilige rote {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Lombarde}}\plain \f1\lang1033\fs22  mit einfachem Fleuronn\u233 \'e9; Rubrikatorvorgaben auf dem unteren Rand (nur stellenweise erhalten).}

