\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 120\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 146\plain \f1\super\lang1033\fs24 v\plain \f1\scaps\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Meditationes}}\plain \f1\lang1033\fs26 . (120\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 122\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 >De celesti gloria.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Tanta est pulchritudo iusticie}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 ex timore amittendi\plain \f1\lang1033\fs26 . Genannte Autoren: {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Ancelmus}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Augustinus}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Bernardus}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Bonaventura}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezper[4].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Crisostomus}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezper[5].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Gregorius}}\plain \f1\lang1033\fs26  ({\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Moralia in Iob}}\plain \f1\lang1033\fs26 ), {\field{\*\fldinst HYPERLINK "hida://bezper[6].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hieronymus}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezper[7].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Petrus Blesensis}}\plain \f1\lang1033\fs26 . (123\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 127\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 >De morte.< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Dic, ubi sunt reges, ubi principes}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 que sit patrie celestis suavitatis \plain \f1\lang1033\fs26 [!] \plain \f1\i\lang1033\fs26 atque du\plain \f1\lang1033\fs26 <\plain \f1\i\lang1033\fs26 l\plain \f1\lang1033\fs26 >\plain \f1\i\lang1033\fs26 cedo. Plura ibi\plain \f1\lang1033\fs26 . Genannte Autoren und Quellen: Augustinus ({\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De spiritu et anima}}\plain \f1\lang1033\fs26 ), Bernardus ({\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Meditationes}}\plain \f1\lang1033\fs26 ), {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Biblia}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezper[8].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Gregorius}}\plain \f1\lang1033\fs26  ({\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Super Hiezechielem}}\plain \f1\lang1033\fs26 ), Hieronymus, {\field{\*\fldinst HYPERLINK "hida://bezwrk[6].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Horologium <sapientiae}}\plain \f1\lang1033\fs26 >, {\field{\*\fldinst HYPERLINK "hida://bezper[10].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Innocentius}}\plain \f1\i\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[7].6930/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 De miseria humane condicionis}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezper[11].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Petrus Damiani}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 philosophus\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[8].6930/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Vita Johannis Elemosinarii}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 (BHL Nr. 4388). (128\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 130\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 >De beneficiis dei.< {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Sicut rivo proprio non asscribitur}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 quo est deo accepcior\plain \f1\lang1033\fs26 . Genannte Autoren und Quellen: Augustinus, Bernardus ({\field{\*\fldinst HYPERLINK "hida://bezwrk[9].6930/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Super cantica}}\plain \f1\lang1033\fs26 ), Gregorius, {\field{\*\fldinst HYPERLINK "hida://bezwrk[10].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De profectibus <religiosorum}}\plain \f1\lang1033\fs26 > ({\field{\*\fldinst HYPERLINK "hida://bezper[12].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 David de Augusta}}\plain \f1\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[11].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De exterioris et interioris hominis compositione}}\plain \f1\lang1033\fs26 , Lib. 3). (131\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 135\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 >De extremo iudicio.< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 O peccator, quid erit de te}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 cum essem deus apparens homo\plain \f1\lang1033\fs26 . Genannte Autoren und Quellen: {\field{\*\fldinst HYPERLINK "hida://bezper[13].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Ambrosius}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Ancelmus/Anselmus\plain \f1\lang1033\fs26 , Augustinus, Bernardus ({\field{\*\fldinst HYPERLINK "hida://bezwrk[12].6930/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 super \u8218 \'82Qui habitat\rquote }}\plain \f1\lang1033\fs26 ), Biblia, {\field{\*\fldinst HYPERLINK "hida://bezper[14].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Climachus}}\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Crisostomus\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezper[15].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Effrem}}\plain \f1\lang1033\fs26 , Gregorius ({\field{\*\fldinst HYPERLINK "hida://bezwrk[13].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Homilien}}\plain \f1\lang1033\fs26 ), Hieronymus, {\field{\*\fldinst HYPERLINK "hida://bezper[16].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Leo papa}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[14].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Passionale}}\plain \f1\lang1033\fs26 . (135\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 140\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 >De penis inferni.< {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Deus assit. Tanta est in inferno oblivio}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 quia peccavimus\plain \f1\lang1033\fs26 . Genannte Autoren und Quellen: Augustinus, Bernardus (Meditationes), Biblia, \plain \f1\i\lang1033\fs26 Clymacus/Climacus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Crisostomus\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezper[18].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Fulgencius}}\plain \f1\lang1033\fs26 , Gregorius (Homiliae), \plain \f1\i\lang1033\fs26 Liber de timore \plain \f1\lang1033\fs26 ({\field{\*\fldinst HYPERLINK "hida://bezper[19].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Petrus Reginaldetus}}\plain \f1\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[15].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Speculum finalis retributionis}}\plain \f1\lang1033\fs26 ), Hieronymus, Horologium <sapientiae>. (140\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 143\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 >Meditacio circa mortem domini.< {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 O vos omnes \u8230 \'85 }}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 [Lam 1, 12]. }}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Bernardus: Tunc in capite oculos habemus}}\plain \f1\i\lang1033\fs26  \plain \f1\i\lang1033\fs26 \u8230 \'85 \endash  \u8230 \'85 ut animam suam ponat quis pro amicis\plain \f1\lang1033\fs26 . Genannte Autoren und Quellen: Bernardus, Biblia. (143\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 146\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 >De peccatis.< {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Cum peccare cogitas}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \plain \f1\lang1033\fs26 (145\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 )\plain \f1\i\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezper[20].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Seneca}}\plain \f1\i\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Cum hominibus pacem habe, bellum cum viciis}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 (vgl. Walther II Nr. 35931a) \plain \f1\i\lang1033\fs26 \u8230 \'85 \endash  \u8230 \'85 et timore iudicii. >Deo gracias. Oretur pro scriptore.< \plain \f1\lang1033\fs26 Genannte Autoren und Quellen: \plain \f1\i\lang1033\fs26 Ancelmus\plain \f1\lang1033\fs26 , \plain \f1\i\lang1033\fs26 Anselmus in Similitudinibus\plain \f1\lang1033\fs26 , Augustinus ({\field{\*\fldinst HYPERLINK "hida://bezwrk[16].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 De spiritu et littera}}\plain \f1\lang1033\fs26 ), {\field{\*\fldinst HYPERLINK "hida://bezper[21].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Beda}}\plain \f1\lang1033\fs26 , Bernardus, Biblia, \plain \f1\i\lang1033\fs26 Crisostomus\plain \f1\lang1033\fs26 , Gregorius ({\field{\*\fldinst HYPERLINK "hida://bezwrk[17].6930/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 super Ezechielem}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[18].6930/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Omelia}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[19].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Moralia}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[20].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Registrum epistularum}}\plain \f1\lang1033\fs26 ), \plain \f1\i\lang1033\fs26 Hostiensis \plain \f1\lang1033\fs26 ({\field{\*\fldinst HYPERLINK "hida://bezper[22].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Henricus de Segusia ?}}\plain \f1\lang1033\fs26 ), {\field{\*\fldinst HYPERLINK "hida://bezper[23].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Hugo Argentinensis}}\plain \f1\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[21].6930/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Compendium theologie}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezper[24].4100/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Isidorus}}\plain \f1\lang1033\fs26 , De profectibus <religiosorum> (David de Augusta: De exterioris et interioris hominis compositione, Lib. 3), Seneca, {\field{\*\fldinst HYPERLINK "hida://bezwrk[22].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Sententiae (?)}}\plain \f1\lang1033\fs26 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[23].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 Summa vitiorum (?)}}\plain \f1\lang1033\fs26 . }

