\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 9\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Henricus Millingen}}\plain \f1\scaps\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Sermones dominicales super epistulas}}\plain \f1\lang1033\fs26 ]. \plain \f1\i\lang1033\fs26 In dominica lxx\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs26 . Super epistula 1 Cor ix. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Nescitis, quod hii, qui in stadio currunt, omnes quidem currunt, sed unus accipit bravium}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17  [I Cor 9,24], }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 id est clenodium sive premium, pro quo curritur. Hoc est, qui primo venerit ad metam, omnes alii vacui recedunt. Ideo dicit apostolus: Sic currite}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17  \u8230 \'85 [I Cor 9,24]}}\plain \f1\lang1033\fs26  \plain \f1\i\lang1033\fs26 \u8230 \'85 \endash  \u8230 \'85 id est perversus ende mysdedich gevonden werd. \plain \f1\lang1033\fs26 (2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Nota: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Cum sanctus Johannes vidisset multos ex pharizeis et saduceis}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 quodcumque ergo proponit, facere bonum statim inchoet\plain \f1\lang1033\fs26 . Es folgen Predigtentw\u252 \'fcrfe zu folgenden Anl\u228 \'e4ssen: T4, T11, T17, T19, T1\endash T3, T7, T12\endash 14 (Siglen nach Schneyer). Der letzte Text: (9\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 In octava pasce. Epistola. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Tanta est solemnitas et sanctitas dei pasce, quod octave eius durant usque ad penthecostes}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \endash  \u8230 \'85 quoniam Christus est veritas. Hec testificacio etc. ut habetur infra circa finem\plain \f1\lang1033\fs26 . Zum letzten Text vgl. Bl. 350\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 .}

