\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 349\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 354\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  \plain \f1\scaps\lang1033\fs26 [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Henricus Millingen}}\plain \f1\scaps\lang1033\fs26 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Sermones dominicales super epistulas}}\plain \f1\scaps\lang1033\fs26  \plain \f1\scaps\lang1033\fs26 (Entw\plain \f1\scaps\lang1033\fs26 \u252 \'fc\plain \f1\scaps\lang1033\fs26 rfe)]\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Epistula in die pasce.\plain \f1\lang1033\fs26 <\plain \f1\i\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Hoc apostolus admonet in epistola presentis diei, quam scripsit ad Cor 1 capitulo v }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 [I Cor 5,7]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 : Expurgate, inquit, vetus fermentum}}\plain \f1\i\lang1033\fs26  \plain \f1\i\lang1033\fs26 \u8230 \'85 \endash  \u8230 \'85 et proximos edificemus bonis exemplis. \plain \f1\lang1033\fs26 Es folgen Texte zu T31, T29 (vgl. 9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ), T30, T32, T33, T24, T15, T18, T20, T21, T23 (Siglen nach Schneyer). Auf Bl. 354\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  ein kurzer Nachtrag zu sermo in secunda feria paschae.}

