\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 28\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 \endash 53\plain \f1\super\lang1033\fs24 r\plain \f1\scaps\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Fundamentum aeternae felicitatis}}\plain \f1\lang1033\fs26 . >\plain \f1\i\lang1033\fs26 Incipit fundamentum eterne felicitatis seu christiane religionis summe utilissimum\plain \f1\lang1033\fs26 .< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Duodecim sunt articuli fidei, secundum quod xii sunt apostoli}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \plain \f1\lang1033\fs26 (40\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 De donis sancti spiritus. Septem sunt dona sancti spiritus. Unde versus: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Sap \u183 \'b7 intel \u183 \'b7 con \u183 \'b7 for \u183 \'b7 sci \u183 \'b7 pi \u183 \'b7 ti \u183 \'b7 collige dona}}\plain \f1\lang1033\fs26 ; (40\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Septem sunt opera misericordie corporalia. Unde versus: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Visito, poto, cibo, redimo}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 \u8230 \'85 (Walther I Nr. 20647; Walther II Nr. 33805, Vers 1); \plain \f1\i\lang1033\fs26 Septem sunt opera misericordie spiritualia. Unde versus: {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Corripe, suade, doce, dimitte}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 \u8230 \'85 (Walther I Nr. 3368); \plain \f1\i\lang1033\fs26 Octo sunt beatitudines anime. Versus: Paupertas, spiritus mitis, lugens miseransque / Justiciam petere, cor mundum pa. persequensque\plain \f1\lang1033\fs26 ; (41\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Novem sunt peccata aliena, que patent in his versibus: {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Iussio, consilium}}\plain \f1\i\lang1033\fs26  \plain \f1\lang1033\fs26 \u8230 \'85 (Walther I Nr. 9990); \plain \f1\i\lang1033\fs26 Sex sunt peccata in spiritum sanctum \plain \f1\lang1033\fs26 (\u8230 \'85). \plain \f1\i\lang1033\fs26 Versus: {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Impugnans verum}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \plain \f1\lang1033\fs26 (Walther I Nr. 8817); (49\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Versus: {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Sunt pueri puri}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \plain \f1\lang1033\fs26 (Walther II 19350); (51\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Unde versus: {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Bis duo notavi}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \plain \f1\lang1033\fs26 (vgl. Walther II Nr. 2037 und ebd. Nr. 2175); (52\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Versus: {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs26\chcbpat17 Nunc lege, nunc ora}}\plain \f1\i\lang1033\fs26  \u8230 \'85 \plain \f1\lang1033\fs26 (Walther II Nr. 19350, vgl. ebd. Nr. 19348 und Walther I 12451) (\u8230 \'85) \plain \f1\i\lang1033\fs26 \endash  \u8230 \'85 qui sit in eternum benedictus. \plain \f1\lang1033\fs26 >\plain \f1\i\lang1033\fs26 Finit fundamentum felicitatis eterne\plain \f1\lang1033\fs26 .< \endash  Druck: GW 10426 f.}

