\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 195\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 197\plain \f1\super\lang1033\fs24 v\plain \f1\caps\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\caps\lang1033\fs26\chcbpat17 Compendium vitae religiosae}}\plain \f1\lang1033\fs26 . Es folgen: \plain \f1\i\lang1033\fs26 Duo principalia legis mandata, 7 dona sancti spiritus, 7 principales virtutes, vii sacramenta ecclesie, vii opera misericordie corporalia, vii opera misericordie spiritualia, vii dotes hominis glorificati, decem mandata legis dei\plain \f1\lang1033\fs26 , (195\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 xii consilia evangelica, que Christus adiecit decalogo mandatorum legis\plain \f1\lang1033\fs26 , (196\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 viii benedictiones iustorum, vii peccata mortalia, 7 virtutes contrarie, septem peccata in spiritum sanctum, ix peccata aliena\plain \f1\lang1033\fs26 , (196\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Quatuor peccata clamantia ad deum, sex etates mundi, septem etates hominis, septem vicia capitalia, septem species superbie, septem species invidie\plain \f1\lang1033\fs26 , (197\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Septem species ire, accidie, avaricie, gule, luxurie, Quatuor virtutes morales, septem species fidei, 7 species spei\plain \f1\lang1033\fs26 , (197\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26 ) \plain \f1\i\lang1033\fs26 Septem species caritatis, iusticie, prudencie, fortitudinis, temperancie; xii fructus hominis spiritus\plain \f1\lang1033\fs26 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

