\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 189\plain \f1\super\lang1033\fs24 r\plain \f1\scaps\lang1033\fs26  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs26\chcbpat17 Versus de signis zodiaci}}\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Nil capiti facies, aries cum luna refulget \plain \f1\lang1033\fs26 ... \plain \f1\i\lang1033\fs26 \endash  \plain \f1\lang1033\fs26 ... \plain \f1\i\lang1033\fs26 carpe viam tucius, pocius, sic sumpta salubris\plain \f1\lang1033\fs26 . \endash  Exzerpt aus dem {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs26\chcbpat17 \ldblquote Regimen sanitatis Salernitanum\rdblquote }}\plain \f1\lang1033\fs26 . \plain \f2\lang1024\fs26 Walther I Nr. 11780. Thorndike/Kibre Sp. 912. Vgl. G. Rosi\u324 \'f1ska, Scientific writings (s.o.), S. 254, Nr. 1262. \plain \f1\lang1033\fs26 Vgl. auch B. Michael, Die mittelalterlichen Handschriften der Wissenschaftlichen Bibliothek Soest, Wiesbaden 1990, S. 215 f.}

