\pard\fi0\li0\tx705\tx1410\tx2130\tx2835\tx3540\tx4245\tx4950\tx5670\tx6375\tx7080\tx7785\tx8490\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 Landmann S. 233 \u183 \'b7 St\u252 \'fcwer S. 76, Nr. 71 (Kurzbeschreibung) \u183 \'b7 Kostbarkeiten Werden S. [10] \u183 \'b7 Kr\u228 \'e4mer S. 827 \u183 \'b7 Vergessene Zeiten S. 52, Nr. 33 (mit Abbildung S. 51) \u183 \'b7 B. C. Barker-Benfield, The Werden \u8218 \'82Heptateuch\lquote , in: Anglo-Saxon England 20, 1991, S. 43\endash 64, hier S. 47, Anm. 20 \u183 \'b7 Handschriftencensus Rheinland Nr. 645 \u183 \'b7 Jahrtausend der M\u246 \'f6nche S. 246.}

