\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs26 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs26 \endash 11\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs26  [\plain \f1\scaps\lang1033\fs26 Alexander de Villa Dei: Summarium biblicum\plain \f1\lang1033\fs26 ]. AT: \plain \f1\i\lang1033\fs26 >Genesis.<Sex, prohibet, peccant, Abel, Enoch, arca fit, intrant \plain \f1\lang1033\fs26 ... \u220 \'dcber den Merkw\u246 \'f6rtern Glossen: 1. \plain \f1\i\lang1033\fs26 dierum opera\plain \f1\lang1033\fs26 , 2. \plain \f1\i\lang1033\fs26 fructum ligni sciencie boni et mali\plain \f1\lang1033\fs26 , 3. \plain \f1\i\lang1033\fs26 Adam et Eva\plain \f1\lang1033\fs26 , 4. \plain \f1\i\lang1033\fs26 occiditur a Cayn\plain \f1\lang1033\fs26 , 5. \plain \f1\i\lang1033\fs26 transfertur in paradisum\plain \f1\lang1033\fs26 , 6. \plain \f1\i\lang1033\fs26 a Noe\plain \f1\lang1033\fs26 , 7. \plain \f1\i\lang1033\fs26 Noe et filii cum uxoribus archam \plain \f1\lang1033\fs26 ... NT: \plain \f1\i\lang1033\fs26 Natus, adoratur, lotum, temptat, docet, orat \plain \f1\lang1033\fs26 ... \u220 \'dcber den Merkw\u246 \'f6rtern Glossen: 1. \plain \f1\i\lang1033\fs26 est Christus in Bethleem\plain \f1\lang1033\fs26 , 2. \plain \f1\i\lang1033\fs26 a magis\plain \f1\lang1033\fs26 , 3. \plain \f1\i\lang1033\fs26 Christum in Iordane\plain \f1\lang1033\fs26 , 4. \plain \f1\i\lang1033\fs26 Christum diabolus in deserto\plain \f1\lang1033\fs26 , 5. \plain \f1\i\lang1033\fs26 Christus in monte\plain \f1\lang1033\fs26 , 6. \plain \f1\i\lang1033\fs26 dicens pater noster \plain \f1\lang1033\fs26 ... \endash  ... \plain \f1\i\lang1033\fs26 Flebunt, ad cenam, surgunt, sponsam, venio iam\plain \f1\lang1033\fs26 . \u220 \'dcber den letzten Merkw\u246 \'f6rtern Glossen: 20. \plain \f1\i\lang1033\fs26 mortui\plain \f1\lang1033\fs26 , 21. \plain \f1\i\lang1033\fs26 ornatam viro suo\plain \f1\lang1033\fs26 , 22. \plain \f1\i\lang1033\fs26 dicit sponsus\plain \f1\lang1033\fs26 . \plain \f1\i\lang1033\fs26 Versus divine scripture termino fine. Deo gracias\plain \f1\lang1033\fs26 . \endash  Stegm\u252 \'fcller RB Nr. 1175; Interlinearglossen vgl. ebd. Nr. 1182,2; Walther I Nr. 17610; Hamesse/Szyller Nr. 30549; CALMA Bd. 1,2, S. 177, ALE 41, Nr. 10. VL\plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs26  Bd. 11, Sp. 59 ff. \endash  12 leer.}

